async function render_interactive_canvas(params, userSettings) {
  return params.htmlSource;
}

async function update_interactive_canvas(params, userSettings, authorizedResources) {
  var previous =
    (authorizedResources && authorizedResources.previousRunOutput) || '';

  if (typeof previous !== 'string' || !previous.length) {
    throw new Error(
      'No previously rendered interactive canvas found to patch. Call `render_interactive_canvas` first to render the initial HTML, then use `update_interactive_canvas` for follow-up edits.',
    );
  }

  var edits = params && params.edits;
  if (!Array.isArray(edits) || edits.length === 0) {
    throw new Error(
      '`edits` must be a non-empty array of {oldText, newText} objects.',
    );
  }

  var html = previous;
  for (var i = 0; i < edits.length; i++) {
    var edit = edits[i] || {};
    var oldText = edit.oldText;
    var newText = edit.newText;

    if (typeof oldText !== 'string' || typeof newText !== 'string') {
      throw new Error(
        'Edit #' +
          (i + 1) +
          ' must have string `oldText` and `newText` properties.',
      );
    }
    if (!oldText.length) {
      throw new Error(
        'Edit #' +
          (i + 1) +
          ' has an empty `oldText`. Provide a non-empty substring to match.',
      );
    }

    var firstIndex = html.indexOf(oldText);
    if (firstIndex === -1) {
      throw new Error(
        'Edit #' +
          (i + 1) +
          ": `oldText` was not found in the current HTML. Make sure it is copied EXACTLY (including whitespace and casing) from the current HTML, or fall back to `render_interactive_canvas` with the full updated HTML.",
      );
    }
    var lastIndex = html.lastIndexOf(oldText);
    if (firstIndex !== lastIndex) {
      throw new Error(
        'Edit #' +
          (i + 1) +
          ": `oldText` matched more than once in the current HTML. Include more surrounding context so it matches exactly once.",
      );
    }

    html =
      html.slice(0, firstIndex) + newText + html.slice(firstIndex + oldText.length);
  }

  return html;
}

async function read_interactive_canvas_source(params, userSettings, authorizedResources) {
  const source = authorizedResources?.previousRunOutput;
  if (typeof source !== 'string' || !source.length) {
    throw new Error('No interactive canvas source found. Call render_interactive_canvas first.');
  }
  return source;
}

async function search_interactive_canvas_source(
  params,
  userSettings,
  authorizedResources,
) {
  const source = authorizedResources?.previousRunOutput;
  if (typeof source !== 'string' || !source.length) {
    throw new Error('No interactive canvas source found. Call render_interactive_canvas first.');
  }
  if (typeof params.keyword !== 'string' || !params.keyword.trim()) {
    throw new Error('keyword must be a non-empty string.');
  }
  const limit = params.limit ?? 50;
  if (!Number.isInteger(limit) || limit < 1 || limit > 200) {
    throw new Error('limit must be an integer from 1 to 200.');
  }

  const lines = source.split(/\r\n|\n|\r/);
  const keyword = params.keyword.toLowerCase();
  const matches = [];
  let totalMatches = 0;
  lines.forEach((line, index) => {
    if (line.toLowerCase().includes(keyword)) {
      totalMatches++;
      if (matches.length < limit) {
        matches.push(`${index + 1}: ${line}`);
      }
    }
  });

  return [
    `${totalMatches} matching lines; showing ${matches.length}. Source has ${lines.length} lines.`,
    ...matches,
  ].join('\n');
}

async function read_interactive_canvas_lines(params, userSettings, authorizedResources) {
  const source = authorizedResources?.previousRunOutput;
  if (typeof source !== 'string' || !source.length) {
    throw new Error('No interactive canvas source found. Call render_interactive_canvas first.');
  }
  const { startLine, endLine } = params;
  if (
    !Number.isInteger(startLine) ||
    !Number.isInteger(endLine) ||
    startLine < 1 ||
    endLine < startLine
  ) {
    throw new Error('Use integer line numbers with 1 <= startLine <= endLine.');
  }

  const lines = source.split(/\r\n|\n|\r/);
  if (startLine > lines.length) {
    throw new Error(
      `startLine exceeds the source length of ${lines.length} lines.`,
    );
  }
  const lastLine = Math.min(endLine, lines.length);
  return [
    `Lines ${startLine}-${lastLine} of ${lines.length}:`,
    ...lines
      .slice(startLine - 1, lastLine)
      .map((line, index) => `${startLine + index}: ${line}`),
  ].join('\n');
}
